"""Render the JSON schema of a playbook document as `docs/reference/playbook/schema.md`."""

import json
from pathlib import Path

ROOT = Path(__file__).parents[2]
SCHEMA = ROOT / "playbook" / "src" / "playbook" / "playbooks" / "playbook.schema.json"
PAGE = ROOT / "docs" / "reference" / "playbook" / "schema.md"

HEADER = """<!--
SPDX-FileCopyrightText: Manta contributors
SPDX-License-Identifier: CC-BY-4.0
-->
<!-- Generated by tools/docs/gen_playbook_schema.py from playbook.schema.json. Do not edit: run `pixi run docs-playbook-schema`. -->

# Playbook schema

This page lists every definition in the JSON schema of a playbook document, `playbook/src/playbook/playbooks/playbook.schema.json`.
It is generated from that file, which `python -m playbook.playbooks.schema` writes from the document models.
A playbook document is a [{root}](#{anchor}).
For what each key does, see [Playbook syntax](syntax.md).

"""


def anchor(name: str) -> str:
    return name.lower()


def ref_name(ref: str) -> str:
    return ref.rsplit("/", 1)[-1]


def literal(value: object) -> str:
    return f"`{json.dumps(value)}`"


def type_of(schema: dict, nested: bool = False) -> str:
    if "$ref" in schema:
        name = ref_name(schema["$ref"])
        return f"[{name}](#{anchor(name)})"
    if "const" in schema:
        return literal(schema["const"])
    options = schema.get("anyOf") or schema.get("oneOf")
    if options or "enum" in schema:
        listed = [type_of(option) for option in options] if options else []
        joined = " or ".join(listed or [literal(value) for value in schema["enum"]])
        return f"({joined})" if nested else joined
    kind = schema.get("type")
    if kind == "array":
        items = schema.get("items")
        return f"list of {type_of(items, nested=True)}" if items else "list"
    if kind == "object" and "patternProperties" in schema:
        [value] = schema["patternProperties"].values()
        return f"mapping of name to {type_of(value, nested=True)}"
    if kind == "object":
        return "mapping"
    return f"`{kind}`" if kind else "any value"


def constraints(schema: dict, prefix: str = "") -> list[str]:
    found = []
    if "pattern" in schema:
        found.append(f"{prefix}matches `{schema['pattern']}`")
    for pattern, value in schema.get("patternProperties", {}).items():
        found.append(f"names of {prefix}match `{pattern}`" if prefix else f"names match `{pattern}`")
        found.extend(constraints(value, f"{prefix}each value "))
    if "minItems" in schema:
        found.append(f"{prefix}at least {schema['minItems']} item{'s' * (schema['minItems'] != 1)}")
    if "items" in schema:
        found.extend(constraints(schema["items"], f"{prefix}each item "))
    if "exclusiveMinimum" in schema:
        found.append(f"{prefix}greater than {schema['exclusiveMinimum']}")
    if "minimum" in schema:
        found.append(f"{prefix}at least {schema['minimum']}")
    if "discriminator" in schema:
        found.append(f"{prefix}picked by `{schema['discriminator']['propertyName']}`")
    for option in schema.get("anyOf", []) + schema.get("oneOf", []):
        found.extend(constraints(option, prefix))
    return list(dict.fromkeys(found))


def cell(text: str) -> str:
    return text.replace("\n", " ")


def refs_in(value: object) -> list[str]:
    if isinstance(value, dict):
        own = [ref_name(value["$ref"])] if "$ref" in value else []
        return own + [name for item in value.values() for name in refs_in(item)]
    if isinstance(value, list):
        return [name for item in value for name in refs_in(item)]
    return []


def ordered(defs: dict[str, dict], root: str) -> list[str]:
    order = [root]
    for name in order:
        order.extend(found for found in dict.fromkeys(refs_in(defs[name])) if found not in order)
    return order + sorted(set(defs) - set(order))


def definition(name: str, schema: dict) -> str:
    lines = [f"## {name} {{#{anchor(name)}}}", ""]
    if "description" in schema:
        lines += [schema["description"], ""]
    properties = schema.get("properties", {})
    required = set(schema.get("required", []))
    described = any("description" in prop for prop in properties.values())
    columns = ["Key", "Type", "Required", "Default", "Constraints"] + (
        ["Description"] if described else []
    )
    lines += ["| " + " | ".join(columns) + " |", "|" + " --- |" * len(columns)]
    for key, prop in properties.items():
        row = [
            f"`{key}`",
            type_of(prop),
            "yes" if key in required else "no",
            literal(prop["default"]) if "default" in prop else "",
            "; ".join(constraints(prop)),
        ] + ([prop.get("description", "")] if described else [])
        lines.append("| " + " | ".join(cell(text) for text in row) + " |")
    if schema.get("additionalProperties") is False:
        lines += ["", f"`{name}` accepts no other keys."]
    return "\n".join(lines) + "\n"


def render(schema: dict) -> str:
    defs = schema["$defs"]
    root = ref_name(schema["$ref"])
    header = HEADER.format(root=root, anchor=anchor(root))
    return header + "\n".join(definition(name, defs[name]) for name in ordered(defs, root))


def main() -> None:
    schema = json.loads(SCHEMA.read_text())
    PAGE.write_text(render(schema), encoding="utf-8")


if __name__ == "__main__":
    main()
